var a=`0257-stuffat-tal-fenek`;var i=`world-0257`;var n=`MT`;var r=`southern-europe`;var o=4;var s=288;var l={en:`Stuffat tal-Fenek`,ua:`Тушкований кролик по-мальтійськи`};var d={en:`A traditional Malta dish made with rabbit meat, garlic, bay leaf, rosemary. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Мальта. Основні інгредієнти: кролятина, часник, лавровий лист, розмарин. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 180 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 180 хвилин.`,t:[`marinating`],m:180,i:[[`rabbit-meat`,950,`g`],[`dry-red-wine`,350,`ml`],[`garlic`,4,`clove`],[`bay-leaf`,2,`leaf`],[`rosemary`,2,`sprig`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,180,`g`],[`extra-virgin-olive-oil`,50,`ml`],[`tomato-paste`,50,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 100 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 100 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:100,i:[[`water`,450,`ml`],[`carrot`,170,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var g={slug:a,id:i,country:`MT`,region:r,servings:4,minutes:288,title:l,text:d,steps:u};export{n as country,g as default,i as id,s as minutes,r as region,o as servings,a as slug,u as steps,d as text,l as title};